import hmac
def valid_csrf(expected, submitted):
 return bool(expected and submitted and hmac.compare_digest(expected,submitted))

SENSITIVE={'password','token','authorization','secret'}
def redact(data):
 return {k:('[REDACTED]' if k.lower() in SENSITIVE else v) for k,v in data.items()}
print(redact({'user':'alice','password':'demo'}))

import hashlib,hmac
def verify(candidate,salt,expected):
 actual=hashlib.scrypt(candidate.encode(),salt=salt,n=2**14,r=8,p=1)
 return hmac.compare_digest(actual,expected)

blocked={'password','password123','qwerty123'}
